// Build the atomic upgrade script from canonical migrations; never alter their history.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
const directory=new URL('../supabase/migrations/',import.meta.url);
const files=readdirSync(directory).filter(file=>/^\d{14}_.+\.sql$/.test(file)).sort();
const baseline=files.slice(0,6).map(file=>file.slice(0,14));
if(baseline.at(-1)!=='20261008145137')throw Error('Unexpected baseline; review before generating the upgrade');
let sql=`-- Existing installations with the six original baseline migrations only.
-- Generated by scripts/generate-update.mjs; execute as one complete transaction.
begin;
do $elas_update$
begin
 perform pg_advisory_xact_lock(hashtext('elas_app_schema_update'));
 if (select count(*) from supabase_migrations.schema_migrations where version=any(array[${baseline.map(v=>`'${v}'`).join(',')}]))<>6 then
  raise exception 'As seis migrations de base precisam estar aplicadas antes desta atualização.';
 end if;
`;
for(const file of files.slice(6)){
 const version=file.slice(0,14),name=file.slice(15,-4),body=readFileSync(new URL(file,directory),'utf8'),delimiter=`$elas_m${version}$`;
 if(body.includes(delimiter)||body.includes('$elas_update$'))throw Error('Migration conflicts with generated delimiters');
 sql+=` if not exists(select 1 from supabase_migrations.schema_migrations where version='${version}') then\n  execute ${delimiter}${body}${delimiter};\n  insert into supabase_migrations.schema_migrations(version,name,statements) values('${version}','${name}',array[${delimiter}${body}${delimiter}]);\n end if;\n`;
}
sql+='end\n$elas_update$;\ncommit;\n';
writeFileSync(new URL('../supabase/ATUALIZACAO.sql',import.meta.url),sql);
console.log(`Generated atomic upgrade with ${files.length} canonical migration versions.`);
